from collect import append_tag

def test_no_leak_between_calls():
    first = append_tag("a")
    second = append_tag("b")
    assert first == ["a"]
    assert second == ["b"]

def test_explicit_list_reused():
    box = ["x"]
    assert append_tag("y", box) == ["x", "y"]


from recursion import depth

def test_depth_nested():
    assert depth([1, [2, [3]]]) == 3

def test_depth_empty():
    assert depth([]) == 1

def test_depth_scalar():
    assert depth(7) == 0

def test_depth_deep():
    assert depth([[[[]]]]) == 4
